import React from 'react';
import { Typography, List } from 'antd';

const { Title, Paragraph } = Typography;

function Home() {
    const skills = [
        'JavaScript (ES6+)',
        'React, Redux, Context API',
        'HTML5, CSS3, Ant Design',
        'REST API, Axios, Git/GitHub',
        'Базові знання Node.js',
    ];

    return (
        <Typography>
            <Title level={2}>Привіт! Я, Половнєва Альона </Title>
            <Paragraph>
                Frontend-розробник (Junior / Навчаюсь)
                Фокусуюсь на розробці SPA з React та сучасними фронтенд-технологіями. Маю базові знання в створенні UI, роботі з REST API та адаптивній верстці. Активно вивчаю JavaScript, HTML, CSS, React, Git
                і прагну застосувати навички на реальних проєктах.
            </Paragraph>

            <Title level={4}>Навички:</Title>
            <List
                bordered
                dataSource={skills}
                renderItem={(item) => <List.Item>{item}</List.Item>}
                style={{ maxWidth: 500 }}
            />
        </Typography>
    );
}

export default Home;
